namespace ClinicaEsteticaWeb.Services;
public class WebSessionMiddleware { private readonly RequestDelegate _next; public WebSessionMiddleware(RequestDelegate next)=>_next=next; public async Task InvokeAsync(HttpContext ctx,WebSessionService sessions){var path=ctx.Request.Path.Value??"/";if(path.StartsWith("/Account",StringComparison.OrdinalIgnoreCase)||path.StartsWith("/css",StringComparison.OrdinalIgnoreCase)||path.StartsWith("/favicon",StringComparison.OrdinalIgnoreCase)){await _next(ctx);return;}if(!sessions.Validate(ctx)){ctx.Response.Redirect("/Account/Login?expired=1");return;}await _next(ctx);} }
